function obterPerfisUsuario() {
    try {
        const raw = sessionStorage.getItem('UserLogin');
        if (!raw) return [];
        const arr = JSON.parse(raw);
        const user = Array.isArray(arr) ? arr[0] : null;
        const nucleo = String(user?.nucleo || '').toLowerCase();
        return nucleo
            .split(',')
            .map((p) => p.trim())
            .filter((p) => p !== '');
    } catch (e) {
        return [];
    }
}

